<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\ClientIdentity\Application\Usecase\List;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Features\Access\ClientIdentity\Application\Service\Visibility\ClientIdentityVisibilityService;
use Civi\Lughauth\Features\Access\ClientIdentity\Domain\Gateway\ClientIdentityReadGateway;
use Civi\Lughauth\Features\Access\ClientIdentity\Domain\Gateway\ClientIdentityFilter;
use Civi\Lughauth\Features\Access\ClientIdentity\Domain\Gateway\ClientIdentityCursor;
use Civi\Lughauth\Features\Access\ClientIdentity\Domain\Gateway\ClientIdentityAttributesSlide;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class ClientIdentityListUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly ClientIdentityVisibilityService $visibility,
        private readonly ClientIdentityReadGateway $reader
    ) {
    }

    public function allowList(): Allow
    {
        $this->logDebug("Check allow of list usecase for Client identity");
        $span = $this->startSpan("Check allow of list usecase for Client identity");
        try {
            $result = $this->dispatcher->dispatch(new ClientIdentityListAllowDecision(Allow::allowed('list', 'Allowed to list by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function count(ClientIdentityFilter $filter): int
    {
        $this->logDebug("Run list usecase for Client identity");
        $span = $this->startSpan("Run list usecase for Client identity");
        try {
            $allow = $this->allowList();
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to list Client identity');
            }
            return $this->visibility->countVisibles($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function list(ClientIdentityFilter $filter, ?ClientIdentityCursor $cursor = null): ClientIdentityAttributesSlide
    {
        $this->logDebug("Run list usecase for Client identity");
        $span = $this->startSpan("Run list usecase for Client identity");
        try {
            $allow = $this->allowList();
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to list');
            }
            $slide = $this->visibility->listVisibles($filter, $cursor);
            return new ClientIdentityAttributesSlide($slide->nextCursor(), array_map(fn ($item) => $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($item)), $slide->values()));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
